package com.nequard.analytics;
import com.nequard.auth.OrganizationAccessService;import com.nequard.network.Device;import com.nequard.network.DeviceRepository;import com.nequard.monitoring.MetricSnapshotRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/analytics") public class AnalyticsController{private final MetricSnapshotRepository repo;private final DeviceRepository devices;private final OrganizationAccessService access;public AnalyticsController(MetricSnapshotRepository r,DeviceRepository d,OrganizationAccessService a){repo=r;devices=d;access=a;}@GetMapping("/device/{deviceId}")public Map<String,Object> device(Authentication a,@PathVariable UUID deviceId){Device d=devices.findById(deviceId).orElseThrow(()->new NoSuchElementException("DEVICE_NOT_FOUND"));if(!access.canAccess(a,d.getOrganizationId()))throw new SecurityException("TENANT_ACCESS_DENIED");var rows=repo.findTop100ByDeviceIdOrderByRecordedAtDesc(deviceId);double avgCpu=rows.stream().filter(x->x.getCpuPercent()!=null).mapToDouble(x->x.getCpuPercent()).average().orElse(0);double avgMem=rows.stream().filter(x->x.getMemoryPercent()!=null).mapToDouble(x->x.getMemoryPercent()).average().orElse(0);return Map.of("samples",rows.size(),"averageCpuPercent",avgCpu,"averageMemoryPercent",avgMem);}}